'use strict';
/*
 * Dead Rooms: an unofficial recreation of Sean Cooper's Boxhead: 2Play Rooms
 * (2007). Canvas 2D graphics and Web Audio sound; no original image, sound
 * or font assets are used.
 *
 * Rules, tables and room layouts were read from the original binary
 * (boxhead2play.swf, sha256 34ff145d96891ddea20278700c8b1fb6fd6273ca0e71b73d
 * 8bdf0df183fdbece, the file linked from the publisher's game page). Class
 * and symbol names in the comments below are the original ActionScript names,
 * so every value can be checked against a decompile. docs/frontend-research.md
 * lists the sources, the method and what is still approximated.
 *
 * Simulation units are the original's: positions in map cells, time in logic
 * ticks. The original runs 25 logic ticks a second at normal speed (CMain.mFPS);
 * update(dt) runs whole ticks from an accumulator so any caller step works.
 */

// ─── Geometry and look (rendering only) ─────────────────────────────────────
const CELL = 32;                                  // CMap_Cell.mCellSize
const VIEW_COLS = 20, VIEW_ROWS = 15;             // the original 640 × 480 stage
const W = VIEW_COLS * CELL, H = VIEW_ROWS * CELL; // logical view in pixels
const WALL_H = 40;
const FY = 0.66, FZ = 0.75;                       // how character depth and height reach the screen
const VIEW_Y = 0.75, VIEW_Z = 0.66;               // direction toward the camera
const SHADOW_X = -0.6, SHADOW_Y = 0.22;           // shadow offset per pixel of height
const LIGHT = [0.49, 0.36, 0.79];
const TAU = Math.PI * 2, OCT = Math.PI / 4;
const BARREL_R = 13, BARREL_TALL = 28, BLOCK_TALL = 30;
const FIGURE_SCALE = 0.8;
const OUTLINE = 'rgba(16,17,19,0.9)';
const FONT = '"Barlow Semi Condensed", "Arial Narrow", Arial, sans-serif';
const DISPLAY_FONT = '"Bungee", Impact, "Arial Black", sans-serif';

// ─── Timing ─────────────────────────────────────────────────────────────────
const BASE_FPS = 25;          // CMain.mFPS at normal speed; level tables are built with it
const SPEEDS = [0.5, 1, 2];   // options "Game speed": SLOW, NORMAL, FAST (mGameSpeed 0 means 0.5)
const fps = () => BASE_FPS * game.options.speed;

// ─── Rooms ──────────────────────────────────────────────────────────────────
// The 18 rooms are the exported symbols ROOM_Single_0001 … 0018; every mode
// loads the same symbol. Each room is the original's marker clips, converted
// with the original's own rules (CWorld.InitThings, CWorld_Init, CMap):
//   size     round(_Size width / 32) × round(_Size height / 32); the outer ring
//            of cells is solid (CMap.InitCells: mCollide_EdgeOfMap | Solid).
//   solid    World_Init_CollisionSolid clips (most sit inside the Piece.* art):
//            MarkArea_PP(round(p / 32), round((p + size) / 32)), end-exclusive,
//            flattened as x0,y0,x1,y1.
//   others   cell = floor(registration point / 32), flattened as col,row:
//            World_Init_Barrel / _Wall (fake walls) / _Zombie and _Devil spawn
//            points / _Pickup boxes. players: col,row,rotation°,isPlayer1, in
//            the order the clips are constructed; the last Player1 marker is
//            the start (AddSpawnPoint_Player), all of them are respawn points.
// Names are the level-select captions. Art pieces are drawn with our own boxes.
