const ROOMS = ROOM_DATA.map(d => {
  const pairs = (list, n = 2) => { const out = []; for (let i = 0; i < list.length; i += n) out.push(list.slice(i, i + n)); return out; };
  const grid = [];
  for (let r = 0; r < d.rows; r++) grid.push(new Array(d.cols).fill('.'));
  for (let c = 0; c < d.cols; c++) grid[0][c] = grid[d.rows - 1][c] = '#';
  for (let r = 0; r < d.rows; r++) grid[r][0] = grid[r][d.cols - 1] = '#';
  for (const [x0, y0, x1, y1] of pairs(d.solid, 4)) {
    for (let r = Math.max(0, y0); r < Math.min(d.rows, y1); r++) for (let c = Math.max(0, x0); c < Math.min(d.cols, x1); c++) grid[r][c] = '#';
  }
  const players = pairs(d.players, 4).map(([c, r, deg, first]) => ({ c, r, angle: deg * Math.PI / 180, first: !!first }));
  return {
    name: d.name, id: d.id, cols: d.cols, rows: d.rows,
    map: grid.map(row => row.join('')),
    barrels: pairs(d.barrels), walls: pairs(d.walls), zombieSpawns: pairs(d.zombies), devilSpawns: pairs(d.devils),
    playerSpawns: players, start: players.filter(p => p.first).pop() || players[0], pickups: pairs(d.pickups),
  };
});

