// CUpgrades.InitLists level table (levels 1-100; later levels repeat level 100
// as "(FOREVER)"). Rates are ticks between spawns, counts are zombies alive at
// once (capped again at 60 when spawning), totals are zombies in the level.
function buildLevels(devils) {
  const rows = [null];
  let rate = BASE_FPS, count = 10, total = 10, devilRate = 10 * BASE_FPS, devilCount = 0, devilTotal = 0;
  for (let n = 1; n <= 100; n++) {
    const row = { spawnRate: Math.floor(rate), count: Math.floor(count), total: Math.floor(total), speedUp: Math.min(1 + (n / 100) * 10, 5) };
    rate = Math.max(rate - 1, 1);
    count = Math.min(count + 5, 60);
    total += 5;
    if (devils) {
      Object.assign(row, { devilRate: Math.floor(devilRate), devilCount: Math.floor(devilCount), devilTotal: Math.floor(devilTotal), devilSpeedUp: row.speedUp });
      devilCount = Math.min(n !== 1 ? devilCount + 0.3 : 1, 5);
      devilTotal = n !== 1 ? devilTotal + 0.25 : 1;
      devilRate = Math.max(devilRate - 1, BASE_FPS);
    }
    rows.push(row);
  }
  return rows;
}

